(function(){
'use strict';
var VERSION='2.2.1';
var moneyFmt=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'});
var wizardDraft=[];
var indexCache=null,indexSize=-1;
var renderQueued=false;

function products(){return window.data&&Array.isArray(window.data.products)?window.data.products:[]}
function productById(id){return typeof window.product==='function'?window.product(id):products().find(function(p){return String(p.id)===String(id)})}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
function money(v){return moneyFmt.format(Number(v||0))}
function stock(p){try{var fn=window.__poolShedOriginalProductStockSummary||window.productStockSummary;return fn?fn(p.id):{onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}catch(_){return{onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}}
function isBundle(p){var t=String((p&&p.productType)||(p&&p.structure)||'').toLowerCase();return t==='bundle'||t==='bundle product'}
function linked(p){return Array.isArray(p&&p.bundleItems)?p.bundleItems.filter(function(x){return x&&x.productId&&Number(x.qty)>0}):[]}
function image(p){var src=(p&&(p.imageUrl||p.parentImageUrl))||'';return src?'<img loading="lazy" src="'+esc(src)+'" alt="">':'<span class="bs-thumb-fallback">PS</span>'}
function normaliseText(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function searchIndex(){var list=products();if(indexCache&&indexSize===list.length)return indexCache;indexSize=list.length;indexCache=list.filter(function(p){return p&&!p.deleted&&!p.hiddenFromCatalogue}).map(function(p){return{p:p,text:normaliseText([p.name,p.sku,p.barcode,p.supplierSku,p.brand,p.category,p.supplier].join(' '))}});return indexCache}
function searchProducts(query,excludeId,existing){var q=normaliseText(query);if(q.length<2)return[];var terms=q.split(/\s+/),set=new Set((existing||[]).map(String));return searchIndex().filter(function(row){var p=row.p;if(String(p.id)===String(excludeId)||set.has(String(p.id)))return false;return terms.every(function(t){return row.text.indexOf(t)>=0})}).slice(0,8).map(function(r){return r.p})}
function calc(items){var cost=0,rrp=0,weight=0,available=Infinity,limiter=null,warnings=[];items.forEach(function(row){var p=productById(row.productId);if(!p)return;var q=Math.max(1,Number(row.qty||1));var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var unitCost=isBundle(p)&&s.cost!=null?Number(s.cost):Number(p.cost||0);var unitRrp=isBundle(p)&&s.sell!=null?Number(s.sell):Number(p.rrp||0);var av=Math.floor(Number(s.available||0)/q);cost+=unitCost*q;rrp+=unitRrp*q;weight+=Number(p.weight||0)*q;if(av<available){available=av;limiter=p}if(String(p.status||'Live').toLowerCase().match(/archived|discontinued/))warnings.push((p.sku||p.name)+' is not active.');});if(!items.length)available=0;return{cost:cost,rrp:rrp,weight:weight,available:available===Infinity?0:available,limiter:limiter,warnings:warnings}}
function statusFor(av,need){if(av<=0)return['red','Out of stock'];if(av<need)return['amber','Short stock'];return['green','Ready']}
function resultRow(p){var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var av=Number(s.available||0),st=statusFor(av,1);return '<button type="button" class="bs-result" data-bs-add="'+esc(p.id)+'">'+image(p)+'<span class="bs-result-copy"><strong>'+esc(p.name||'Unnamed product')+'</strong><em>'+esc(p.sku||'No SKU')+(p.barcode?' · '+esc(p.barcode):'')+'</em><small>'+esc(p.brand||p.supplier||'Catalogue product')+'</small></span><span class="bs-result-stock '+st[0]+'"><b>'+av+'</b><small>available</small></span><span class="bs-result-price"><b>'+money(isBundle(p)&&s.sell!=null?s.sell:p.rrp)+'</b><small>RRP</small></span><span class="bs-result-add">Add</span></button>'}
function componentRow(row){var p=productById(row.productId);if(!p)return'';var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var av=Number(s.available||0),q=Math.max(1,Number(row.qty||1)),st=statusFor(av,q);var unitCost=isBundle(p)&&s.cost!=null?s.cost:p.cost,unitRrp=isBundle(p)&&s.sell!=null?s.sell:p.rrp;return '<div class="bs-component" data-bs-component="'+esc(p.id)+'"><div class="bs-product-cell">'+image(p)+'<div><strong>'+esc(p.name||'Unnamed product')+'</strong><span>'+esc(p.sku||'No SKU')+(isBundle(p)?' · Nested bundle':'')+'</span></div></div><label><span>Quantity</span><input type="number" min="1" step="1" value="'+q+'" data-bs-qty="'+esc(p.id)+'"></label><div><span>Available</span><strong class="bs-pill '+st[0]+'">'+av+' · '+st[1]+'</strong></div><div><span>Cost</span><strong>'+money(Number(unitCost||0)*q)+'</strong></div><div><span>RRP</span><strong>'+money(Number(unitRrp||0)*q)+'</strong></div><div class="bs-component-actions"><button type="button" data-bs-open="'+esc(p.id)+'">Open</button><button type="button" class="danger" data-bs-remove="'+esc(p.id)+'" aria-label="Remove component">Remove</button></div></div>'}
function summary(items,sellingPrice){var c=calc(items),sell=Number(sellingPrice||0),profit=sell-c.cost,margin=sell>0?profit/sell*100:0,saving=Math.max(0,c.rrp-sell);return '<aside class="bs-summary"><div class="bs-summary-status '+(c.available>0?'green':'red')+'"><span>Effective bundle stock</span><strong>'+c.available+'</strong><em>'+(c.limiter?'Limited by '+esc(c.limiter.name):'Add components to calculate')+'</em></div><div class="bs-summary-grid"><div><span>Component cost</span><strong>'+money(c.cost)+'</strong></div><div><span>Component RRP</span><strong>'+money(c.rrp)+'</strong></div><div><span>Bundle price</span><strong>'+money(sell)+'</strong></div><div><span>Customer saving</span><strong>'+money(saving)+'</strong></div><div><span>Gross profit</span><strong>'+money(profit)+'</strong></div><div><span>Gross margin</span><strong>'+margin.toFixed(1)+'%</strong></div><div><span>Total weight</span><strong>'+c.weight.toFixed(2)+' kg</strong></div><div><span>Linked products</span><strong>'+items.length+'</strong></div></div>'+(c.warnings.length?'<div class="bs-alert"><strong>Needs attention</strong>'+c.warnings.map(function(w){return'<p>'+esc(w)+'</p>'}).join('')+'</div>':'<div class="bs-ok">Catalogue links and stock calculation are healthy.</div>')+'</aside>'}
function builderShell(opts){var items=opts.items||[],price=Number(opts.price||0);return '<div class="bs-studio" data-bs-mode="'+opts.mode+'"'+(opts.productId?' data-bs-product-id="'+esc(opts.productId)+'"':'')+'><header class="bs-hero"><div><span>POOL SHED · SMART BUNDLE BUILDER</span><h2>Build from your live product catalogue</h2><p>Search and link existing SKUs. Product details, costs, supplier information and stock remain connected to the original catalogue record.</p></div><div class="bs-hero-badges"><span>Virtual product</span><span>No duplicate stock</span><span>Live availability</span></div></header><div class="bs-layout"><main><section class="bs-card bs-search-card"><div class="bs-section-title"><div><span class="bs-step">01</span><div><h3>Add catalogue products</h3><p>Search by product name, SKU, supplier SKU or barcode.</p></div></div><span class="bs-count">'+items.length+' linked</span></div><div class="bs-search-wrap"><span class="bs-search-icon">⌕</span><input type="search" autocomplete="off" data-bs-search placeholder="Start typing a product name, SKU or barcode"><kbd>⌘ K</kbd><div class="bs-results" data-bs-results></div></div><div class="bs-search-help"><span>Fast search</span><span>Exact SKU matching</span><span>Stock shown before adding</span></div></section><section class="bs-card"><div class="bs-section-title"><div><span class="bs-step">02</span><div><h3>Bundle components</h3><p>Every row is linked to the existing Product Hub record.</p></div></div></div><div class="bs-components" data-bs-components>'+(items.length?items.map(componentRow).join(''):'<div class="bs-empty"><span>+</span><strong>No products linked yet</strong><p>Use the smart search above to add the first component.</p></div>')+'</div></section></main>'+summary(items,price)+'</div><div class="bs-footnote"><strong>Stock rule:</strong> availability is calculated from the lowest number of complete bundles possible across every linked component.</div></div>'}
function profileBuilder(p){return builderShell({mode:'profile',productId:p.id,items:linked(p),price:Number(p.bundleManualRrp||p.rrp||0)})+'<div class="bs-savebar"><div><strong>Bundle links use existing catalogue products</strong><span>Saving does not create or duplicate component SKUs.</span></div><button type="button" class="secondary" data-bs-refresh>Refresh stock</button><button type="button" data-bs-save>Save bundle</button></div>'}
function wizardBuilder(form){var price=form&&form.querySelector('[name="rrp"]')?Number(form.querySelector('[name="rrp"]').value||0):0;return '<div class="product-step-heading"><span>06</span><div><h2>Bundle Builder</h2><p>Create the head product, then link components directly from the Product Hub catalogue.</p></div></div><div class="bs-wizard-type"><label>Product structure<select name="structure" data-bs-structure><option>Simple product</option><option>Variant</option><option selected>Bundle</option></select></label><div><strong>This product will be a virtual bundle</strong><p>It will not hold its own physical stock. Stock is allocated from the linked component SKUs.</p></div></div>'+builderShell({mode:'wizard',items:wizardDraft,price:price})+'<textarea name="bundleComponents" data-bs-hidden-components hidden></textarea><input name="bundleItemsJson" data-bs-hidden-json type="hidden">'}
function syncWizardHidden(root){var text=wizardDraft.map(function(r){var p=productById(r.productId);return(p?p.sku:r.productId)+' | '+Number(r.qty||1)}).join('\n');var ta=root.querySelector('[data-bs-hidden-components]'),json=root.querySelector('[data-bs-hidden-json]');if(ta)ta.value=text;if(json)json.value=JSON.stringify(wizardDraft)}
function mountProfileLegacy(){var old=document.querySelector('[data-product-field$="|bundleEnabled"]');if(!old)return;var id=(old.dataset.productField||'').split('|')[0],p=productById(id);if(!p)return;var container=old.closest('.product-tab-grid')||old.closest('.product-tab-card');if(container&&!container.querySelector('.bs-studio'))container.outerHTML=profileBuilder(p)}
function mountWizard(){var panel=document.querySelector('[data-product-step-panel="variants"]');if(!panel||panel.dataset.bsMounted==='1')return;var form=panel.closest('form');var structure=panel.querySelector('[name="structure"]');if(structure&&structure.value!=='Bundle')return;panel.dataset.bsMounted='1';panel.innerHTML=wizardBuilder(form);syncWizardHidden(panel)}
function scheduleMount(){if(renderQueued)return;renderQueued=true;requestAnimationFrame(function(){renderQueued=false;mountProfileLegacy();mountWizard()})}
function rootFrom(el){return el.closest('.bs-studio')}
function stateFrom(root){if(root.dataset.bsMode==='wizard')return wizardDraft;var p=productById(root.dataset.bsProductId);return p?linked(p):[]}
function rerender(root){if(!root)return;if(root.dataset.bsMode==='wizard'){var panel=root.closest('[data-product-step-panel="variants"]');if(panel){panel.innerHTML=wizardBuilder(panel.closest('form'));syncWizardHidden(panel)}}else{var p=productById(root.dataset.bsProductId);var wrapper=root.parentElement;if(p&&wrapper){var savebar=document.querySelector('.bs-savebar');if(savebar)savebar.remove();root.outerHTML=profileBuilder(p)}}}
function updateSearch(input){var root=rootFrom(input),results=root.querySelector('[data-bs-results]'),items=stateFrom(root),matches=searchProducts(input.value,root.dataset.bsProductId,items.map(function(x){return x.productId}));results.innerHTML=input.value.trim().length<2?'<div class="bs-search-message">Type at least 2 characters to search the Product Hub.</div>':matches.length?matches.map(resultRow).join(''):'<div class="bs-search-message">No matching live catalogue products.</div>';results.classList.add('open')}
function addItem(root,id){var items=stateFrom(root);if(items.some(function(x){return String(x.productId)===String(id)}))return;if(root.dataset.bsMode==='wizard'){wizardDraft=items.concat({productId:id,qty:1,displayOrder:items.length})}else{var p=productById(root.dataset.bsProductId);p.bundleItems=items.concat({productId:id,qty:1,displayOrder:items.length});p.productType='Bundle Product';p.structure='Bundle';p.stockTracked=false}rerender(root)}
function removeItem(root,id){var items=stateFrom(root).filter(function(x){return String(x.productId)!==String(id)});if(root.dataset.bsMode==='wizard')wizardDraft=items;else{var p=productById(root.dataset.bsProductId);p.bundleItems=items}rerender(root)}
function saveProfile(root){var p=productById(root.dataset.bsProductId);if(!p)return;p.productType='Bundle Product';p.structure='Bundle';p.stockTracked=false;p.bundleEnabled='Yes';p.bundleAvailabilityRule='Lowest component availability';p.bundleComponents=linked(p).map(function(r){var x=productById(r.productId);return(x?x.sku:r.productId)+' | '+r.qty}).join('\n');p.updatedAt=new Date().toISOString();if(typeof window.saveAppData==='function')window.saveAppData();if(typeof window.toast==='function')window.toast('Bundle saved with live catalogue links.');if(typeof window.render==='function')window.render()}

document.addEventListener('input',function(e){var search=e.target.closest('[data-bs-search]');if(search){updateSearch(search);return}var qty=e.target.closest('[data-bs-qty]');if(qty){var root=rootFrom(qty),items=stateFrom(root),row=items.find(function(x){return String(x.productId)===String(qty.dataset.bsQty)});if(row)row.qty=Math.max(1,Math.floor(Number(qty.value||1)));if(root.dataset.bsMode==='wizard')syncWizardHidden(root.closest('[data-product-step-panel="variants"]'));return}},true);
document.addEventListener('change',function(e){var structure=e.target.closest('[name="structure"]');if(structure&&structure.value==='Bundle'){var panel=structure.closest('[data-product-step-panel="variants"]');if(panel){panel.dataset.bsMounted='';scheduleMount()}}},true);
document.addEventListener('click',function(e){var add=e.target.closest('[data-bs-add]');if(add){addItem(rootFrom(add),add.dataset.bsAdd);return}var remove=e.target.closest('[data-bs-remove]');if(remove){removeItem(rootFrom(remove),remove.dataset.bsRemove);return}var open=e.target.closest('[data-bs-open]');if(open&&typeof window.openProductProfile==='function'){window.openProductProfile(open.dataset.bsOpen);return}var save=e.target.closest('[data-bs-save]');if(save){saveProfile(document.querySelector('.bs-studio[data-bs-mode="profile"]'));return}var refresh=e.target.closest('[data-bs-refresh]');if(refresh){rerender(document.querySelector('.bs-studio[data-bs-mode="profile"]'));return}},true);
document.addEventListener('keydown',function(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){var input=document.querySelector('.bs-studio [data-bs-search]');if(input){e.preventDefault();input.focus()}}if(e.key==='Escape'){document.querySelectorAll('.bs-results.open').forEach(function(x){x.classList.remove('open')})}},true);
document.addEventListener('click',function(e){if(!e.target.closest('.bs-search-wrap'))document.querySelectorAll('.bs-results.open').forEach(function(x){x.classList.remove('open')})});
document.addEventListener('submit',function(e){var form=e.target;if(!form||!form.querySelector('[data-product-step-panel="variants"]'))return;var structure=form.querySelector('[name="structure"]');if(!structure||structure.value!=='Bundle')return;var panel=form.querySelector('[data-product-step-panel="variants"]');syncWizardHidden(panel);var sku=(form.querySelector('[name="sku"]')||{}).value;setTimeout(function(){var p=products().find(function(x){return x&&!x.deleted&&String(x.sku||'').toLowerCase()===String(sku||'').toLowerCase()});if(!p)return;p.bundleItems=JSON.parse(JSON.stringify(wizardDraft));p.productType='Bundle Product';p.structure='Bundle';p.stockTracked=false;p.bundleEnabled='Yes';p.bundleAvailabilityRule='Lowest component availability';p.bundleComponents=wizardDraft.map(function(r){var x=productById(r.productId);return(x?x.sku:r.productId)+' | '+r.qty}).join('\n');if(typeof window.saveAppData==='function')window.saveAppData();wizardDraft=[]},0)},true);

var oldTab=window.productProfileTabContent;
if(typeof oldTab==='function')window.productProfileTabContent=function(p,s){if(window.productTab==='bundle'&&isBundle(p))return profileBuilder(p);return oldTab(p,s)};
new MutationObserver(scheduleMount).observe(document.documentElement,{childList:true,subtree:true});
scheduleMount();
window.PoolShedBundleStudio={version:VERSION,search:searchProducts,calculate:calc};
})();
